exercise.schema:
CREATE TABLE clinics (id int PRIMARY KEY, name text NOT NULL);
CREATE TABLE patients (id int PRIMARY KEY, clinic_id int NOT NULL REFERENCES clinics(id));
CREATE TABLE visits (id int PRIMARY KEY, patient_id int NOT NULL REFERENCES patients(id), mode text NOT NULL CHECK (mode IN ('in_person', 'video')));
CREATE TABLE invoices (id int PRIMARY KEY, patient_id int NOT NULL REFERENCES patients(id), amount numeric(10,2) NOT NULL);

